  "$defs": {
    "LocalizedText": {
      "$comment": "🌍 Every user-visible string exists in both languages; the document language selects one, there is no default.",
      "type": "object",
      "required": [
        "en",
        "de"
      ],
      "properties": {
        "en": {
          "type": "string",
          "minLength": 1
        },
        "de": {
          "type": "string",
          "minLength": 1
        }
      },
      "additionalProperties": false
    },
    "TaxonomyLeafId": {
      "$comment": "🍃 `<taxonomy section>/<leaf slug>`, the identity of one line of 🖼️assets/📊️viz-taxonomy.md.",
      "type": "string",
      "pattern": "^[0-9]{1,2}/[a-z0-9]+(-[a-z0-9]+)*$"
    },
    "Slug": {
      "$comment": "🏷️ Global, section-free chart-kind name.",
      "type": "string",
      "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
    },
    "Kind": {
      "$comment": "🗂️ What the entry renders: a mark primitive, a chart preset, or a demonstrated kernel capability.",
      "enum": [
        "mark",
        "chart",
        "layout",
        "axis",
        "scale"
      ]
    },
    "Namespace": {
      "$comment": "📦 Taxonomy §76 namespace the renderer lives in, matching the `semio-viz-<namespace>` packages.",
      "type": "string",
      "pattern": "^(kernel|charts|hierarchy|network|flow|geo|spatial|matrix|diagram|scientific|timeline|table|annotation|dashboard|infographic|layout|scale|axis|legend|label|interactionstate|theme)(/[a-z0-9-]+)?$"
    },
    "DemoTable": {
      "$comment": "🧪 Name of a demo table declared in a `%region 🔖️DemoData` block.",
      "type": "string",
      "pattern": "^demo(-[a-z0-9]+)*$"
    },
    "FamilyOptions": {
      "$comment": "🎛️ One family's option vocabulary: `variant` is required, further keys are the real dimensions the family exposes.",
      "type": "object",
      "required": [
        "owner",
        "options"
      ],
      "properties": {
        "owner": {
          "type": "string",
          "minLength": 1
        },
        "options": {
          "type": "object",
          "required": [
            "variant"
          ],
          "additionalProperties": {
            "type": "object",
            "required": [
              "description"
            ],
            "properties": {
              "type": {
                "enum": [
                  "string",
                  "number",
                  "boolean"
                ]
              },
              "default": {
                "type": [
                  "string",
                  "number",
                  "boolean"
                ]
              },
              "enum": {
                "type": "array",
                "minItems": 1,
                "uniqueItems": true,
                "items": {
                  "type": "string"
                }
              },
              "description": {
                "$ref": "#/$defs/LocalizedText"
              }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },
    "TaxonomyGroup": {
      "$comment": "📑 One group heading of the taxonomy, titled in both document languages.",
      "type": "object",
      "required": [
        "title"
      ],
      "properties": {
        "title": {
          "$ref": "#/$defs/LocalizedText"
        }
      },
      "additionalProperties": false
    },
    "TaxonomySection": {
      "$comment": "📚 One chapter of the taxonomy, titled in both document languages for the generated gallery.",
      "type": "object",
      "required": [
        "section",
        "title"
      ],
      "properties": {
        "section": {
          "type": "string",
          "pattern": "^[0-9]{1,2}$"
        },
        "title": {
          "$ref": "#/$defs/LocalizedText"
        }
      },
      "additionalProperties": false
    },
    "DemoTableDeclaration": {
      "$comment": "🧫 A named demo table every catalogue entry may point at through its `data` key.",
      "type": "object",
      "required": [
        "name",
        "columns",
        "description"
      ],
      "properties": {
        "name": {
          "$ref": "#/$defs/DemoTable"
        },
        "columns": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "description": {
          "$ref": "#/$defs/LocalizedText"
        }
      },
      "additionalProperties": false
    },
    "CatalogEntry": {
      "$comment": "📇 One chart kind: a family plus its default options, covering one or more taxonomy leaves.",
      "type": "object",
      "required": [
        "id",
        "slug",
        "title",
        "kind",
        "namespace",
        "family",
        "options",
        "data",
        "covers"
      ],
      "properties": {
        "id": {
          "$ref": "#/$defs/TaxonomyLeafId"
        },
        "slug": {
          "$ref": "#/$defs/Slug"
        },
        "title": {
          "$ref": "#/$defs/LocalizedText"
        },
        "kind": {
          "$ref": "#/$defs/Kind"
        },
        "namespace": {
          "$ref": "#/$defs/Namespace"
        },
        "family": {
          "$ref": "#/$defs/Slug"
        },
        "options": {
          "type": "object",
          "required": [
            "variant"
          ],
          "additionalProperties": {
            "type": [
              "string",
              "number",
              "boolean"
            ]
          }
        },
        "data": {
          "$ref": "#/$defs/DemoTable"
        },
        "covers": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/TaxonomyLeafId"
          }
        }
      },
      "additionalProperties": false
    },
    "ProbeRecord": {
      "$comment": "🔬 One line of `\\jobname.probe.jsonl`, written by semio-viz-probe.sty and read by 🔨️modules/🧪️viz-probe.",
      "type": "object",
      "required": [
        "case",
        "scenario",
        "key",
        "values"
      ],
      "properties": {
        "case": {
          "type": "string",
          "minLength": 1
        },
        "scenario": {
          "type": "string",
          "minLength": 1
        },
        "key": {
          "type": "string",
          "minLength": 1
        },
        "values": {
          "type": "array",
          "items": {
            "type": [
              "number",
              "string"
            ]
          }
        }
      },
      "additionalProperties": false
    },
    "GalleryTheme": {
      "$comment": "🌗 The document appearances a gallery section is rendered in.",
      "enum": [
        "light",
        "dark"
      ]
    },
    "GalleryKindPage": {
      "$comment": "📄️ Where one catalogue kind of a section landed: its one-based page and that page's extracted text.",
      "type": "object",
      "required": [
        "page",
        "text"
      ],
      "properties": {
        "page": {
          "type": "integer",
          "minimum": 1
        },
        "text": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    "GalleryVariantMeasurement": {
      "$comment": "📏️ One rendered gallery variant (section x theme x language): page count, per-kind page and page text, and the rebuild-stable PDF hash.",
      "type": "object",
      "required": [
        "pages",
        "kinds",
        "hash"
      ],
      "properties": {
        "pages": {
          "type": "integer",
          "minimum": 1
        },
        "kinds": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/$defs/GalleryKindPage"
          }
        },
        "hash": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        }
      },
      "additionalProperties": false
    },
    "GalleryRenderEvidence": {
      "$comment": "🖼️ The committed gallery evidence of the `🖼️gallery-render` case, keyed `<section>/<theme>/<language>`; regenerated by `bun ./📜️script.ts test viz fixtures [section…]`, never hand-written.",
      "type": "object",
      "required": [
        "schemaVersion",
        "generatedBy",
        "variants"
      ],
      "properties": {
        "schemaVersion": {
          "const": 1
        },
        "generatedBy": {
          "type": "string"
        },
        "variants": {
          "type": "object",
          "propertyNames": {
            "pattern": "^[a-z0-9-]+/(light|dark)/(en|de)$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/GalleryVariantMeasurement"
          }
        }
      },
      "additionalProperties": false
    },
    "ChartLocalizedText": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "en": {
          "type": "string"
        },
        "de": {
          "type": "string"
        }
      },
      "required": [
        "en",
        "de"
      ]
    },
    "ChartTable": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1
        },
        "columns": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "rows": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": {
              "type": [
                "string",
                "number",
                "boolean",
                "null"
              ]
            }
          }
        }
      },
      "required": [
        "name",
        "columns",
        "rows"
      ]
    },
    "ChartEncoding": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "column": {
          "type": "string"
        },
        "scale": {
          "type": "string"
        },
        "value": {
          "type": [
            "string",
            "number",
            "boolean"
          ]
        }
      }
    },
    "ChartScale": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "name": {
          "type": "string"
        },
        "kind": {
          "type": "string",
          "enum": [
            "linear",
            "log",
            "pow",
            "sqrt",
            "symlog",
            "identity",
            "ordinal",
            "band",
            "point",
            "quantile",
            "quantize",
            "threshold",
            "sequential",
            "diverging",
            "temporal"
          ]
        },
        "domain": {
          "type": "array",
          "items": {
            "type": [
              "number",
              "string"
            ]
          }
        },
        "range": {
          "type": "array",
          "items": {
            "type": [
              "number",
              "string"
            ]
          }
        },
        "options": {
          "$ref": "#/$defs/ChartScaleOptions"
        }
      },
      "allOf": [
        {
          "anyOf": [
            {
              "properties": {
                "kind": {
                  "enum": [
                    "linear",
                    "log",
                    "pow",
                    "sqrt",
                    "symlog",
                    "identity",
                    "ordinal",
                    "quantile",
                    "quantize",
                    "threshold",
                    "sequential",
                    "diverging",
                    "temporal"
                  ]
                }
              }
            },
            {
              "properties": {
                "kind": {
                  "enum": [
                    "band",
                    "point"
                  ]
                },
                "options": {
                  "properties": {
                    "unknown": false
                  }
                }
              }
            }
          ]
        }
      ],
      "required": [
        "name",
        "kind",
        "domain",
        "range"
      ]
    },
    "ChartTransform": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "kind": {
          "type": "string",
          "enum": [
            "filter",
            "sort",
            "group",
            "aggregate",
            "rollup",
            "summary",
            "fold",
            "pivot",
            "join",
            "window",
            "normalize",
            "cumulative",
            "bin",
            "stack",
            "quantile",
            "kde",
            "regression"
          ]
        },
        "options": {
          "type": "object",
          "additionalProperties": {
            "anyOf": [
              {
                "type": [
                  "string",
                  "number",
                  "boolean"
                ]
              },
              {
                "type": "array",
                "items": {
                  "type": [
                    "string",
                    "number",
                    "boolean"
                  ]
                }
              }
            ]
          }
        }
      },
      "required": [
        "kind"
      ]
    },
