          "titleSize": 7.2,
          "scale": "x",
          "orient": "bottom",
          "labelFont": "SemioSans",
          "titleFont": "SemioMono",
          "strokeRole": "hairline",
          "strokeColorRole": "border-emphasized",
          "minorStrokeColorRole": "border-normal",
